        ["The Mod Manager, MelonLoader and all mods have been removed."] = new[] { "Mod-Manager, MelonLoader und alle Mods wurden entfernt.", "Le gestionnaire de mods, MelonLoader et tous les mods ont été supprimés.", "Менеджер модов, MelonLoader и все моды удалены.", "模组管理器、MelonLoader 和所有模组均已移除。" },
        ["The Mod Manager has been removed. MelonLoader and your mods are still installed."] = new[] { "Der Mod-Manager wurde entfernt. MelonLoader und deine Mods sind weiterhin installiert.", "Le gestionnaire de mods a été supprimé. MelonLoader et tes mods sont toujours installés.", "Менеджер модов удалён. MelonLoader и ваши моды остались установлены.", "模组管理器已移除。MelonLoader 和你的模组仍保留安装。" },

        // ───────── MelonLoader page ─────────
        ["The mod loader. Mods only load when MelonLoader is installed."] = new[] { "Der Mod-Loader. Mods werden nur geladen, wenn MelonLoader installiert ist.", "Le chargeur de mods. Les mods ne se chargent que si MelonLoader est installé.", "Загрузчик модов. Моды работают только с установленным MelonLoader.", "模组加载器。只有安装了 MelonLoader，模组才会加载。" },
        ["Install MelonLoader"] = new[] { "MelonLoader installieren", "Installer MelonLoader", "Установить MelonLoader", "安装 MelonLoader" },
        ["Install from zip…"] = new[] { "Aus ZIP installieren…", "Installer depuis un zip…", "Установить из zip…", "从 zip 安装…" },
        ["Troubleshooting"] = new[] { "Fehlerbehebung", "Dépannage", "Решение проблем", "故障排查" },
        ["MelonLoader writes everything it does to Latest.log - the first place to look when a mod doesn't load."] = new[] { "MelonLoader schreibt alles, was es tut, in die Latest.log - die erste Anlaufstelle, wenn ein Mod nicht lädt.", "MelonLoader écrit tout ce qu'il fait dans Latest.log - le premier endroit à consulter quand un mod ne se charge pas.", "MelonLoader записывает всё, что делает, в Latest.log - туда стоит заглянуть первым делом, если мод не загружается.", "MelonLoader 会将所有操作写入 Latest.log - 模组无法加载时请先查看此文件。" },
        ["Open Latest.log"] = new[] { "Latest.log öffnen", "Ouvrir Latest.log", "Открыть Latest.log", "打开 Latest.log" },
        ["Open MelonLoader folder"] = new[] { "MelonLoader-Ordner öffnen", "Ouvrir le dossier MelonLoader", "Открыть папку MelonLoader", "打开 MelonLoader 文件夹" },
        ["Good to know"] = new[] { "Gut zu wissen", "Bon à savoir", "Полезно знать", "须知" },
        ["The first launch after installing takes a few minutes while MelonLoader prepares the game."] = new[] { "Der erste Start nach der Installation dauert ein paar Minuten, während MelonLoader das Spiel vorbereitet.", "Le premier lancement après l'installation prend quelques minutes, le temps que MelonLoader prépare le jeu.", "Первый запуск после установки занимает несколько минут, пока MelonLoader готовит игру.", "安装后首次启动需要几分钟，MelonLoader 正在准备游戏。" },
        ["Updating MelonLoader only replaces MelonLoader itself - your Mods, UserData (mod settings and models), Plugins and UserLibs folders aren't touched."] = new[] { "Ein Update ersetzt nur MelonLoader selbst - deine Ordner Mods, UserData (Mod-Einstellungen und Modelle), Plugins und UserLibs bleiben unberührt.", "La mise à jour ne remplace que MelonLoader - tes dossiers Mods, UserData (paramètres et modèles des mods), Plugins et UserLibs ne sont pas touchés.", "Обновление заменяет только сам MelonLoader - папки Mods, UserData (настройки модов и модели), Plugins и UserLibs не затрагиваются.", "更新只会替换 MelonLoader 本身 - 不会改动你的 Mods、UserData（模组设置和模型）、Plugins 和 UserLibs 文件夹。" },
        ["Uninstalling moves files to the Recycle Bin. You choose whether your mods are removed too."] = new[] { "Beim Deinstallieren landen die Dateien im Papierkorb. Du entscheidest, ob auch deine Mods entfernt werden.", "La désinstallation envoie les fichiers dans la Corbeille. Tu choisis si tes mods sont aussi supprimés.", "При удалении файлы попадают в корзину. Вы сами решаете, удалять ли заодно моды.", "卸载会将文件移到回收站。你可以选择是否同时移除模组。" },
        ["DO NOT play Broken Arrow with Anti-Cheat turned on while MelonLoader is installed"] = new[] { "Spiele Broken Arrow NICHT mit aktiviertem Anti-Cheat, solange MelonLoader installiert ist", "NE joue PAS à Broken Arrow avec l'anti-triche activé tant que MelonLoader est installé", "НЕ играйте в Broken Arrow с включённым античитом, пока установлен MelonLoader", "安装 MelonLoader 期间，切勿在开启反作弊的情况下游玩 Broken Arrow" },
        ["Anti-Cheat can detect MelonLoader and mods, and that can get your account banned. With MelonLoader installed, only play with the Anti-Cheat disabled option (Right click on Broken Arrow → Properties → General → Selected Launch Option → Play Anti-Cheat Disabled)."] = new[] {
            "Das Anti-Cheat kann MelonLoader und Mods erkennen, und dafür kann dein Konto gesperrt werden. Solange MelonLoader installiert ist, spiele nur mit der Option ohne Anti-Cheat (Rechtsklick auf Broken Arrow → Eigenschaften → Allgemein → Startoption → Play Anti-Cheat Disabled).",
            "L'anti-triche peut détecter MelonLoader et les mods, ce qui peut faire bannir ton compte. Avec MelonLoader installé, joue uniquement avec l'option sans anti-triche (clic droit sur Broken Arrow → Propriétés → Général → Option de lancement → Play Anti-Cheat Disabled).",
            "Античит может обнаружить MelonLoader и моды, и за это ваш аккаунт могут заблокировать. Пока установлен MelonLoader, играйте только с отключённым античитом (ПКМ по Broken Arrow → Свойства → Общие → Параметр запуска → Play Anti-Cheat Disabled).",
            "反作弊可以检测到 MelonLoader 和模组，这可能导致你的账号被封禁。安装 MelonLoader 期间，请只使用关闭反作弊的选项游玩（右键点击 Broken Arrow → 属性 → 通用 → 启动选项 → Play Anti-Cheat Disabled）。" },
        ["For normal online matches (quick match, ranked, skirmish), uninstall MelonLoader first; untick \"Also delete all mods\" if you want to keep your mods; select \"Play Broken Arrow\" in Steam Launch Option."] = new[] {
            "Für normale Online-Matches (Schnelles Spiel, Ranked, Gefecht) deinstalliere zuerst MelonLoader; entferne das Häkchen bei „Auch alle Mods löschen“, wenn du deine Mods behalten willst; wähle in der Steam-Startoption „Play Broken Arrow“.",
            "Pour les parties en ligne normales (partie rapide, classée, escarmouche), désinstalle d'abord MelonLoader ; décoche « Supprimer aussi tous les mods » si tu veux garder tes mods ; choisis « Play Broken Arrow » dans l'option de lancement Steam.",
            "Для обычных онлайн-матчей (быстрый матч, рейтинговые, схватка) сначала удалите MelonLoader; снимите галочку «Также удалить все моды», если хотите сохранить моды; выберите «Play Broken Arrow» в параметре запуска Steam.",
            "进行普通在线对战（快速匹配、排位、遭遇战）前，请先卸载 MelonLoader；如果想保留模组，请取消勾选“同时删除所有模组”；并在 Steam 启动选项中选择“Play Broken Arrow”。" },
        ["MelonLoader {0} is installed"] = new[] { "MelonLoader {0} ist installiert", "MelonLoader {0} est installé", "MelonLoader {0} установлен", "MelonLoader {0} 已安装" },
        ["MelonLoader {0} is incomplete"] = new[] { "MelonLoader {0} ist unvollständig", "MelonLoader {0} est incomplet", "MelonLoader {0} установлен не полностью", "MelonLoader {0} 不完整" },
        ["Installed {0:g}. Press Update to get the newest release."] = new[] { "Installiert am {0:g}. Klicke auf Aktualisieren, um die neueste Version zu holen.", "Installé le {0:g}. Clique sur Mettre à jour pour obtenir la dernière version.", "Установлен {0:g}. Нажмите «Обновить», чтобы получить последнюю версию.", "安装于 {0:g}。点击“更新”获取最新版本。" },
        ["Installed. Press Update to get the newest release."] = new[] { "Installiert. Klicke auf Aktualisieren, um die neueste Version zu holen.", "Installé. Clique sur Mettre à jour pour obtenir la dernière version.", "Установлен. Нажмите «Обновить», чтобы получить последнюю версию.", "已安装。点击“更新”获取最新版本。" },
        ["version.dll is missing from the game folder, so MelonLoader won't start. Reinstall it."] = new[] { "version.dll fehlt im Spielordner, daher startet MelonLoader nicht. Installiere es neu.", "version.dll manque dans le dossier du jeu, MelonLoader ne démarrera donc pas. Réinstalle-le.", "В папке игры нет version.dll, поэтому MelonLoader не запустится. Переустановите его.", "游戏文件夹中缺少 version.dll，MelonLoader 无法启动。请重新安装。" },
        ["Update to latest"] = new[] { "Auf neueste Version aktualisieren", "Mettre à jour", "Обновить до последней", "更新到最新版" },
        ["Reinstall"] = new[] { "Neu installieren", "Réinstaller", "Переустановить", "重新安装" },
        ["MelonLoader is not installed"] = new[] { "MelonLoader ist nicht installiert", "MelonLoader n'est pas installé", "MelonLoader не установлен", "未安装 MelonLoader" },
        ["Install it with one click - the latest release is downloaded from GitHub."] = new[] { "Installiere es mit einem Klick - die neueste Version wird von GitHub geladen.", "Installe-le en un clic - la dernière version est téléchargée depuis GitHub.", "Установите в один клик - последняя версия скачивается с GitHub.", "一键安装 - 将从 GitHub 下载最新版本。" },
        ["Downloads come from {0} ({1}). You can change this in Settings → Advanced."] = new[] { "Downloads kommen von {0} ({1}). Das kannst du unter Einstellungen → Erweitert ändern.", "Les téléchargements proviennent de {0} ({1}). Tu peux changer cela dans Paramètres → Avancé.", "Загрузка идёт с {0} ({1}). Это можно изменить в Настройки → Дополнительно.", "下载来源：{0}（{1}）。可在 设置 → 高级 中更改。" },

        // ───────── Settings page ─────────
        ["Language, game folder, where files go, and the Mod Manager itself."] = new[] { "Sprache, Spielordner, wohin Dateien kommen, und der Mod-Manager selbst.", "Langue, dossier du jeu, emplacement des fichiers et le gestionnaire de mods lui-même.", "Язык, папка игры, куда кладутся файлы, и сам менеджер модов.", "语言、游戏文件夹、文件存放位置，以及模组管理器本身。" },
        ["Language"] = new[] { "Sprache", "Langue", "Язык", "语言" },
        ["The Mod Manager restarts to switch the language."] = new[] { "Der Mod-Manager startet neu, um die Sprache zu wechseln.", "Le gestionnaire de mods redémarre pour changer de langue.", "Для смены языка менеджер модов перезапустится.", "切换语言需要重启模组管理器。" },
        ["Game folder"] = new[] { "Spielordner", "Dossier du jeu", "Папка игры", "游戏文件夹" },
        ["The folder that contains the game's .exe. Usually found automatically from Steam."] = new[] { "Der Ordner mit der .exe des Spiels. Wird meist automatisch über Steam gefunden.", "Le dossier qui contient le .exe du jeu. Généralement trouvé automatiquement via Steam.", "Папка, где лежит .exe игры. Обычно находится автоматически через Steam.", "包含游戏 .exe 的文件夹。通常会通过 Steam 自动找到。" },
        ["Browse…"] = new[] { "Durchsuchen…", "Parcourir…", "Обзор…", "浏览…" },
        ["Auto-detect"] = new[] { "Automatisch finden", "Détection auto", "Найти автоматически", "自动检测" },
        ["Open folders"] = new[] { "Ordner öffnen", "Ouvrir les dossiers", "Открыть папки", "打开文件夹" },
        [".bamod mod packages"] = new[] { ".bamod-Mod-Pakete", "Paquets de mods .bamod", "Пакеты модов .bamod", ".bamod 模组包" },
        ["Double-clicking a .bamod file opens the Mod Manager and installs it. This is set up automatically when the Mod Manager starts."] = new[] { "Ein Doppelklick auf eine .bamod-Datei öffnet den Mod-Manager und installiert sie. Das wird beim Start des Mod-Managers automatisch eingerichtet.", "Double-cliquer sur un fichier .bamod ouvre le gestionnaire de mods et l'installe. C'est configuré automatiquement au lancement du gestionnaire.", "Двойной щелчок по файлу .bamod открывает менеджер модов и устанавливает его. Это настраивается автоматически при запуске менеджера.", "双击 .bamod 文件会打开模组管理器并安装它。模组管理器启动时会自动完成此设置。" },
        ["Open .bamod files with this Mod Manager"] = new[] { ".bamod-Dateien mit diesem Mod-Manager öffnen", "Ouvrir les fichiers .bamod avec ce gestionnaire", "Открывать файлы .bamod этим менеджером", "使用此模组管理器打开 .bamod 文件" },
        ["Stop opening .bamod files"] = new[] { ".bamod-Dateien nicht mehr öffnen", "Ne plus ouvrir les fichiers .bamod", "Не открывать файлы .bamod", "停止打开 .bamod 文件" },
        [".bamod files now open with this Mod Manager."] = new[] { ".bamod-Dateien öffnen sich jetzt mit diesem Mod-Manager.", "Les fichiers .bamod s'ouvrent désormais avec ce gestionnaire.", "Теперь файлы .bamod открываются этим менеджером модов.", ".bamod 文件现在将用此模组管理器打开。" },
        ["Couldn't register .bamod files."] = new[] { ".bamod-Dateien konnten nicht registriert werden.", "Impossible d'associer les fichiers .bamod.", "Не удалось связать файлы .bamod.", "无法关联 .bamod 文件。" },
        [".bamod files are no longer opened by the Mod Manager."] = new[] { ".bamod-Dateien werden nicht mehr vom Mod-Manager geöffnet.", "Les fichiers .bamod ne sont plus ouverts par le gestionnaire de mods.", "Файлы .bamod больше не открываются менеджером модов.", "模组管理器将不再打开 .bamod 文件。" },
        [".bamod files open with this Mod Manager"] = new[] { ".bamod-Dateien öffnen sich mit diesem Mod-Manager", "Les fichiers .bamod s'ouvrent avec ce gestionnaire", "Файлы .bamod открываются этим менеджером", ".bamod 文件将用此模组管理器打开" },
        [".bamod files don't open with this Mod Manager"] = new[] { ".bamod-Dateien öffnen sich nicht mit diesem Mod-Manager", "Les fichiers .bamod ne s'ouvrent pas avec ce gestionnaire", "Файлы .bamod не открываются этим менеджером", ".bamod 文件不会用此模组管理器打开" },
        ["For modders"] = new[] { "Für Modder", "Pour les moddeurs", "Для авторов модов", "面向模组作者" },
        ["Pack your mod into a .bamod: one file with your DLLs, models, picture, description and requirements."] = new[] { "Packe deinen Mod in eine .bamod: eine Datei mit deinen DLLs, Modellen, Bild, Beschreibung und Voraussetzungen.", "Emballe ton mod dans un .bamod : un seul fichier avec tes DLL, modèles, image, description et dépendances.", "Упакуйте мод в .bamod: один файл с вашими DLL, моделями, картинкой, описанием и зависимостями.", "将你的模组打包为 .bamod：一个文件包含 DLL、模型、图片、描述和依赖。" },
        ["Create mod package…"] = new[] { "Mod-Paket erstellen…", "Créer un paquet de mod…", "Создать пакет мода…", "创建模组包…" },
        ["Where files go"] = new[] { "Wohin Dateien kommen", "Emplacement des fichiers", "Куда кладутся файлы", "文件存放位置" },
        ["Loose files (a single .dll, .bundle…) are placed by their extension. Mod packages (.bamod / .zip) that contain Mods\\ or UserData\\ folders keep their own layout and don't need rules. Files of these types that you copied into the game folder by hand can also be switched on and off."] = new[] {
            "Einzelne Dateien (eine .dll, .bundle…) werden nach ihrer Endung abgelegt. Mod-Pakete (.bamod / .zip) mit Mods\\- oder UserData\\-Ordnern behalten ihren eigenen Aufbau und brauchen keine Regeln. Dateien dieser Typen, die du von Hand in den Spielordner kopiert hast, lassen sich auch ein- und ausschalten.",
            "Les fichiers isolés (un .dll, un .bundle…) sont placés selon leur extension. Les paquets de mods (.bamod / .zip) qui contiennent des dossiers Mods\\ ou UserData\\ gardent leur propre structure et n'ont pas besoin de règles. Les fichiers de ces types copiés à la main dans le dossier du jeu peuvent aussi être activés et désactivés.",
            "Отдельные файлы (.dll, .bundle…) раскладываются по расширению. Пакеты модов (.bamod / .zip) с папками Mods\\ или UserData\\ сохраняют свою структуру, и правила им не нужны. Файлы этих типов, скопированные в папку игры вручную, тоже можно включать и выключать.",
            "单个文件（.dll、.bundle…）会按扩展名放置。包含 Mods\\ 或 UserData\\ 文件夹的模组包（.bamod / .zip）会保持其自身结构，无需规则。手动复制到游戏文件夹中的这些类型的文件也可以启用或禁用。" },
        ["Add rule"] = new[] { "Regel hinzufügen", "Ajouter une règle", "Добавить правило", "添加规则" },
        ["Save"] = new[] { "Speichern", "Enregistrer", "Сохранить", "保存" },
        ["Reset to default"] = new[] { "Auf Standard zurücksetzen", "Rétablir par défaut", "Сбросить по умолчанию", "恢复默认" },
        ["Advanced"] = new[] { "Erweitert", "Avancé", "Дополнительно", "高级" },
        ["Only change these if the game's folder name or MelonLoader's download location changes."] = new[] { "Ändere das nur, wenn sich der Ordnername des Spiels oder der Download-Ort von MelonLoader ändert.", "Ne modifie ceci que si le nom du dossier du jeu ou l'emplacement de téléchargement de MelonLoader change.", "Меняйте это, только если изменилось имя папки игры или место загрузки MelonLoader.", "仅当游戏文件夹名称或 MelonLoader 下载位置变化时才需要更改。" },
        ["STEAM FOLDER NAME"] = new[] { "STEAM-ORDNERNAME", "NOM DU DOSSIER STEAM", "ИМЯ ПАПКИ В STEAM", "STEAM 文件夹名称" },
        ["MELONLOADER GITHUB REPO"] = new[] { "MELONLOADER-GITHUB-REPO", "DÉPÔT GITHUB DE MELONLOADER", "РЕПОЗИТОРИЙ MELONLOADER НА GITHUB", "MELONLOADER GITHUB 仓库" },
        ["MELONLOADER DOWNLOAD FILE"] = new[] { "MELONLOADER-DOWNLOADDATEI", "FICHIER DE TÉLÉCHARGEMENT MELONLOADER", "ФАЙЛ ЗАГРУЗКИ MELONLOADER", "MELONLOADER 下载文件" },
        ["Steam folder = the folder under steamapps\\common used by Auto-detect."] = new[] { "Steam-Ordner = der Ordner unter steamapps\\common, den „Automatisch finden“ verwendet.", "Dossier Steam = le dossier sous steamapps\\common utilisé par la détection auto.", "Папка Steam - папка в steamapps\\common, которую ищет автопоиск.", "Steam 文件夹 = 自动检测时使用的 steamapps\\common 下的文件夹。" },
